// === Tab: mySketch ===
function setup() {
	//windowHeight = 1500 ; windowWidth = 1500
	createCanvas(windowWidth, windowHeight);

	background(100);

	HG = [0]
	CG = [0]

	pass = 0
	nx = 0 ; ny = 10 ; f = 0
	colorMode(HSB,256)
	noiseDetail(5,.5)

	forestcol = color(80,200,100)
	maptint = color(random(255),255-random(random(255)),255-random(random(255)))
	horizon = floor(windowHeight*.3)
}

function draw() {

	for(var VC=0;VC<5;VC++)
	{
		colorMode(HSB,256)
		for(ny=0;ny<horizon;ny++) //draw the sky
		{
			//all of this is just to figure out coordinates. Perspective doubles as zoom level
			perspective = (.2-ny/windowHeight/2)*32 ; dx = (nx-windowWidth/2)/perspective+windowWidth/2 ; dy = ny/perspective

			//cc is cloud cover. Just a lot of random noises thrown together, honestly
			cc = max(0,max(0,perspective-.15)*sq(sq(sq(perspective/30+noise(dx/200,dy/250+6)/2+noise(dx/200,dy/120)*noise(dx/100+5,dy/60))))*16)

			//then choosing colour
			stroke(color(130+ny/5,96-96*cc,min(240,160+100*cc)*(1-.2*abs(noise(dx/50,dy/30)-.5))))
			point(nx,ny)
		}

		colorMode(RGB,256)
		for(ny=horizon;ny<windowHeight;ny++) //draw the terrain
		{
		//all of this is just to figure out coordinates. Perspective doubles as zoom level
		dx = (nx-windowWidth/2) ; perspective = (ny/windowHeight/2-.05)*4 ;
		dx = dx/perspective/3+windowWidth/2 ; dy = windowHeight-(windowHeight-ny)/perspective/1.5
		//finally distort the coordinates by some noise
		ix = dx+(noise(dx/50,dy/50+15)-.5)*25 ; iy = dy+(noise(dx/50+15,dy/50)-.5)*25

		//basic heightmap
		h = (sqrt(noise(ix/200,iy/200))+sqrt(noise(ix/400,iy/400+3)))/2-sqrt(sq(ix-windowWidth/2)+sq(iy-windowHeight/2))/2500
		//height difference just below the coastline
		h -= (h<.5)/150

		//biome (arid versus humid)
		f = min(45,max(-45,(noise(ix/450+3,iy/450+5)-.5)*175))
		f = abs(f/45)*f

		//m denotes mountainousness
		m = (noise(ix/250+1,iy/250+49)-.5)*.9
		m = lerp(0,m,m*10)
		h += m*(1+abs(noise(ix/50,iy/50+3)-.5))*max(0,min(1,-5+10*h))

		//save height in array
		HG[nx*windowHeight+ny] = h

		//generate colour
											//this long bit just compares the current height with five other pixels
		nc = gc(h*256-128,h*5-HG[nx*windowHeight+ny-2*windowHeight-2]-HG[nx*windowHeight+ny-4*windowHeight]-HG[nx*windowHeight+ny-windowHeight]-HG[nx*windowHeight+ny-2*windowHeight]-HG[nx*windowHeight+ny-1])

		//save colour in array (unused)
		CG[nx*windowHeight+ny] = floor(red(window.color(nc)))+256*floor(green(window.color(nc)))+256*256*floor(blue(window.color(nc)))

		//draw onto screen
		stroke(nc)
		line(nx,ny-max(0,(sqrt(abs(h))-sqrt(.5))*250),nx,ny)
		}
		nx++
	}

	//draw borders (obscures bugs)
	fill(color(0))
	rect(0,0,windowWidth,5)
	rect(0,0,5,windowHeight)
	rect(windowWidth-6,0,5,windowHeight)
	rect(0,windowHeight-7,windowWidth,5)
}

function gc(h,d)
{
	colorMode(HSB,256)
	var nc
	if (h > 0)
		nc = color((65+f)*(1-h/220),130+1.75*f-h*0.5,130-f-h/1.4+sq(h/19)) //land colours
	else
		nc = color(min(180,120-h*1.5),90,max(110,min(110,-40*h)+50+h)) //sea colours
	colorMode(RGB,256)
	if ((HG[nx*windowHeight+ny] % .025)>random(.005)+(HG[nx*windowHeight+ny-2] % .025)) nc = lerpColor(nc,color(255),ny/windowHeight*.075) //light dithering
	nc = lerpColor(nc,color(256*(d>0)),min(.4,abs(d*(h > 0 ? 5 : 2)))) //lights and shadows
	if ((nx % 2) && (ny % 2)) nc = lerpColor(nc,maptint,random(.1)) //grain
	return(nc)
}
